import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"OpenStreetMap Data Guide: Autocomplete Fields and Classification","description":"","frontmatter":{},"headers":[],"relativePath":"osm-data-guide.md","filePath":"osm-data-guide.md","lastUpdated":1781808154000}'),r={name:"osm-data-guide.md"};function c(i,t,s,n,l,m){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="openstreetmap-data-guide-autocomplete-fields-and-classification" tabindex="-1">OpenStreetMap Data Guide: Autocomplete Fields and Classification <a class="header-anchor" href="#openstreetmap-data-guide-autocomplete-fields-and-classification" aria-label="Permalink to &quot;OpenStreetMap Data Guide: Autocomplete Fields and Classification&quot;">​</a></h1><p>This document maps the OpenStreetMap (OSM) data structure, tags, and layers to the <code>auto-complete</code> service&#39;s internal schemas and classification rules.</p><hr><h2 id="_1-layers-tag-ingestion" tabindex="-1">1. Layers &amp; Tag Ingestion <a class="header-anchor" href="#_1-layers-tag-ingestion" aria-label="Permalink to &quot;1. Layers &amp; Tag Ingestion&quot;">​</a></h2><p>The pipeline downloads raw country-level extracts in <code>.osm.pbf</code> format from Geofabrik. It runs <code>osmium tags-filter</code> to generate streamable <code>.geojsonseq</code> layers containing only travel-relevant features.</p><p>We ingest two primary layers:</p><ol><li><strong>Administrative Boundaries</strong>: Scoped to <code>boundary=administrative</code> and selected settlement places (<code>place=city</code>, <code>place=town</code>, etc.).</li><li><strong>Points of Interest (POIs) &amp; Transport Hubs</strong>: Scoped to tourism, leisure, transport, historic, and dining categories.</li></ol><hr><h2 id="_2-naming-multilingual-tag-parsing" tabindex="-1">2. Naming &amp; Multilingual Tag Parsing <a class="header-anchor" href="#_2-naming-multilingual-tag-parsing" aria-label="Permalink to &quot;2. Naming &amp; Multilingual Tag Parsing&quot;">​</a></h2><p>OSM maps features with rich name variations. To enable robust multi-language autocomplete, we extract all naming fields and index them as alternative search terms.</p><h3 id="tag-mapping" tabindex="-1">Tag Mapping <a class="header-anchor" href="#tag-mapping" aria-label="Permalink to &quot;Tag Mapping&quot;">​</a></h3><table tabindex="0"><thead><tr><th>OSM Tag</th><th>Field in Schema</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>NameCanonical</code>, <code>NameDisplay</code></td><td>Primary local/default name of the feature</td></tr><tr><td><code>name:&lt;lang&gt;</code></td><td><code>NamesByLanguage</code></td><td>Language-specific translations (e.g. <code>name:en</code>, <code>name:nl</code>, <code>name:fr</code>)</td></tr><tr><td><code>alt_name</code></td><td><code>NameAltActive</code></td><td>Alternative names used locally</td></tr><tr><td><code>official_name</code></td><td><code>NameAltActive</code></td><td>Official or legal name</td></tr><tr><td><code>old_name</code></td><td><code>NameAltActive</code></td><td>Historic or former name of the place</td></tr><tr><td><code>loc_name</code></td><td><code>NameAltActive</code></td><td>Colloquial or colloquial local name</td></tr><tr><td><code>short_name</code></td><td><code>NameAltActive</code></td><td>Shortened name or code (e.g. <em>AMS</em> for Schiphol)</td></tr><tr><td><code>int_name</code></td><td><code>NameAltActive</code></td><td>International name (transliterations)</td></tr></tbody></table><p><em>Note: All values in <code>NamesByLanguage</code> and alternative name tags are merged, case-insensitively deduplicated, and fed into Meilisearch&#39;s <code>search_terms_flat</code> and <code>name_alt_active</code> fields.</em></p><hr><h2 id="_3-entity-classification-19-class-taxonomy" tabindex="-1">3. Entity Classification (19-Class Taxonomy) <a class="header-anchor" href="#_3-entity-classification-19-class-taxonomy" aria-label="Permalink to &quot;3. Entity Classification (19-Class Taxonomy)&quot;">​</a></h2><p>The pipeline maps the raw tags of features to one of the following 19 classes. Each class is assigned a base popularity score, which is later enriched with population and pageview popularity metrics.</p><table tabindex="0"><thead><tr><th>Class</th><th>Tag Filter criteria</th><th>Base Score</th><th>Description</th></tr></thead><tbody><tr><td><strong>Country</strong></td><td><code>place=country</code></td><td><code>0.75</code></td><td>Sovereign nations and countries</td></tr><tr><td><strong>Airport</strong></td><td><code>aeroway=aerodrome</code> or <code>aeroway=airport</code></td><td><code>0.80</code></td><td>Airports, airfields, heliports</td></tr><tr><td><strong>City</strong></td><td><code>admin_level=6-8</code>, or <code>place=city</code>/<code>town</code>/<code>village</code></td><td><code>0.65</code></td><td>Cities, towns, municipalities, villages</td></tr><tr><td><strong>TrainStation</strong></td><td><code>railway=station</code> or <code>railway=halt</code></td><td><code>0.60</code></td><td>Train stations and railway halts</td></tr><tr><td><strong>TouristAttraction</strong></td><td><code>tourism=attraction</code>/<code>museum</code>/<code>viewpoint</code>/<code>zoo</code>/<code>theme_park</code>/<code>gallery</code>/<code>aquarium</code></td><td><code>0.58</code></td><td>Major tourist destinations, museums, galleries</td></tr><tr><td><strong>Stadium</strong></td><td><code>leisure=stadium</code></td><td><code>0.56</code></td><td>Sports stadiums and arenas</td></tr><tr><td><strong>Region</strong></td><td><code>admin_level=4</code></td><td><code>0.55</code></td><td>States, provinces, administrative regions</td></tr><tr><td><strong>Hotel</strong></td><td><code>tourism=hotel</code>/<code>hostel</code>/<code>motel</code>/<code>guest_house</code>/<code>apartment</code>/<code>camp_site</code>/<code>chalet</code></td><td><code>0.50</code></td><td>Lodgings and tourist accommodations</td></tr><tr><td><strong>HistoricSite</strong></td><td><code>historic=castle</code>/<code>monument</code>/<code>memorial</code>/<code>archaeological_site</code>/<code>ruins</code></td><td><code>0.50</code></td><td>Historic monuments, castles, ruins</td></tr><tr><td><strong>Island</strong></td><td><code>place=island</code> or <code>place=islet</code></td><td><code>0.50</code></td><td>Named islands and islets</td></tr><tr><td><strong>Park</strong></td><td><code>leisure=park</code>/<code>nature_reserve</code>/<code>marina</code> or <code>boundary=national_park</code></td><td><code>0.48</code></td><td>Parks, reserves, national parks</td></tr><tr><td><strong>BusStation</strong></td><td><code>amenity=bus_station</code></td><td><code>0.48</code></td><td>Bus terminals and stations</td></tr><tr><td><strong>FerryTerminal</strong></td><td><code>amenity=ferry_terminal</code></td><td><code>0.48</code></td><td>Passenger ferry terminals</td></tr><tr><td><strong>Beach</strong></td><td><code>natural=beach</code> or <code>leisure=beach_resort</code></td><td><code>0.45</code></td><td>Public beaches and beach resorts</td></tr><tr><td><strong>Neighborhood</strong></td><td><code>admin_level=9-10</code>, or <code>place=suburb</code>/<code>neighbourhood</code>/<code>quarter</code></td><td><code>0.45</code></td><td>City quarters, suburbs, neighborhoods</td></tr><tr><td><strong>Restaurant</strong></td><td><code>amenity=restaurant</code>/<code>cafe</code>/<code>bar</code>/<code>pub</code></td><td><code>0.40</code></td><td>Dining establishments, cafes, bars, pubs</td></tr><tr><td><strong>Entertainment</strong></td><td><code>amenity=theatre</code>/<code>cinema</code>/<code>nightclub</code> or <code>leisure=water_park</code></td><td><code>0.40</code></td><td>Theaters, cinemas, entertainment venues, nightclubs</td></tr><tr><td><strong>NaturalFeature</strong></td><td><code>natural=peak</code>/<code>volcano</code>/<code>cave_entrance</code>/<code>glacier</code></td><td><code>0.38</code></td><td>Mountain peaks, volcanoes, caves</td></tr><tr><td><strong>Shopping</strong></td><td><code>shop=mall</code>/<code>department_store</code></td><td><code>0.38</code></td><td>Shopping malls and department stores</td></tr></tbody></table><hr><h2 id="_4-custom-extracted-attributes" tabindex="-1">4. Custom Extracted Attributes <a class="header-anchor" href="#_4-custom-extracted-attributes" aria-label="Permalink to &quot;4. Custom Extracted Attributes&quot;">​</a></h2><p>In addition to core coordinates and names, we extract entity-specific fields to enrich search matching:</p><h3 id="airport-attributes" tabindex="-1">Airport Attributes <a class="header-anchor" href="#airport-attributes" aria-label="Permalink to &quot;Airport Attributes&quot;">​</a></h3><ul><li><code>iata</code>: 3-letter IATA code (mapped to <code>iata_code</code>, e.g. <em>AMS</em>).</li><li><code>icao</code>: 4-letter ICAO code (mapped to <code>icao_code</code>, e.g. <em>EHAM</em>).</li></ul><h3 id="hotel-attributes" tabindex="-1">Hotel Attributes <a class="header-anchor" href="#hotel-attributes" aria-label="Permalink to &quot;Hotel Attributes&quot;">​</a></h3><ul><li><code>stars</code>: Star rating count (mapped to <code>star_rating</code>, e.g. <em>4</em>).</li><li><code>tourism</code>: Value of the tourism tag (mapped to <code>accommodation_type</code>, e.g. <em>hotel</em>, <em>hostel</em>).</li></ul><h3 id="restaurant-attributes" tabindex="-1">Restaurant Attributes <a class="header-anchor" href="#restaurant-attributes" aria-label="Permalink to &quot;Restaurant Attributes&quot;">​</a></h3><ul><li><code>cuisine</code>: Dynamic cuisine categories (mapped to <code>cuisine</code>, e.g. <em>italian;pizza</em>). Split by semicolon and appended to search terms so users can search by food type.</li></ul>',26)])])}const g=e(r,[["render",c]]);export{p as __pageData,g as default};
